import sys
import subprocess
import requests
from urllib.parse import urlparse

def run_cmd_check(cmd):
    try:
        result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
        return 0, result.stdout[:500] + "\n" if result.stdout else "Command executed successfully"
    except subprocess.CalledProcessError as e:
        return e.returncode, e.stderr[:500] + "\n" if e.stderr else "Command failed"

def run_url_check(url):
    try:
        response = requests.get(url, timeout=5)
        return response.status_code, str(response.status_code)
    except requests.RequestException:
        return -1, "Request failed"

def parse_checks_file(file_path):
    checks = []
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            name, check_type, target = line.split('\t')
            checks.append((name, check_type, target))
    return checks

def generate_report(checks):
    passed = 0
    total = len(checks)
    results = []

    for name, check_type, target in checks:
        if check_type == 'cmd':
            exit_code, detail = run_cmd_check(target)
            result = 'PASS' if exit_code == 0 else 'FAIL'
        elif check_type == 'url':
            status_code, detail = run_url_check(target)
            result = 'PASS' if 200 <= status_code <= 299 else 'FAIL'
        else:
            result = 'FAIL'
            detail = f"Invalid check type: {check_type}"

        passed += 1 if result == 'PASS' else 0
        results.append((name, check_type, result, detail))

    return passed, total, results

def write_report(results, report_path):
    with open(report_path, 'w') as f:
        f.write("<html><head><title>Health Report</title></head><body>\n")
        f.write("<h1>Health Report</h1>\n")
        f.write(f"<p>{passed} of {total} checks passed</p>\n")

        f.write("<table>\n")
        f.write("<tr><th>Name</th><th>Kind</th><th>Result</th><th>Detail</th></tr>\n")

        for name, check_type, result, detail in results:
            f.write(f"<tr><td>{name}</td><td>{check_type}</td><td>{result}</td><td>{detail}</td></tr>\n")

        f.write("</table>\n")
        f.write("</body></html>")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python healthcheck.py checks.tsv report.html", file=sys.stderr)
        sys.exit(1)

    checks_file = sys.argv[1]
    report_file = sys.argv[2]

    checks = parse_checks_file(checks_file)
    passed, total, results = generate_report(checks)

    if passed != total:
        sys.exit(1)

    write_report(results, report_file)
